# %% [markdown]
# # CASMI 2026 — specs_scratch R2: class-vote CV re-run + discrimination kill gate (Colab)
#
# **Generated by `scratch_pkg/tools/mk_notebook.py r2_audit_colab` from `scratch_pkg/drivers/r2_audit_colab.py` —
# do not hand-edit.** Gates R2.2 / R2.3 pre-registered in `specs/specs_scratch/gate_report.md` (R2 section).
# Needs `casmi_2026/casmi26-scratch-pool/` **v2** (with `pool_npc.parquet`, from `casmi_scratch_r2_npc_colab.ipynb`).
#
# Runtime: **CPU, High-RAM**. Stage results are cached in `casmi_2026/_r2_audit/`; a re-run skips finished stages.
#
# | stage | gate |
# |---|---|
# | cv | R2.2: delta-list vote purity vs majority baseline and coverage, NPClassifier labels on both sides; table-only purity |
# | disc | R2.3: on the R1b pool, sv = 0, β = 0.10: truth P(voted) above the window median in ≥ 60% of voted molecules, and more truths moved up than down |
#
# Paste the final printout back into the chat.

# %%
import json, os, subprocess, sys, time
from pathlib import Path

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path(os.environ.get("CASMI_INPUT", "/content/drive/MyDrive/casmi_2026"))
POOL_DIR = ROOT / "casmi26-scratch-pool"
OUT = ROOT / "_r2_audit"
WORKERS = os.cpu_count() or 2
PKG_FILES = None  # @@PKG_FILES@@
PKG_ROOT = Path("/content/pkg")
for rel, src in PKG_FILES.items():
    p = PKG_ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src, encoding="utf-8")
sys.path.insert(0, str(PKG_ROOT))
OUT.mkdir(parents=True, exist_ok=True)

RDKIT_PIN = "2026.03.3"
r_ = subprocess.run([sys.executable, "-m", "pip", "install", "-q", f"rdkit=={RDKIT_PIN}"], capture_output=True, text=True)
if r_.returncode != 0:
    raise RuntimeError("rdkit install failed:\n" + r_.stdout[-2000:] + "\n" + r_.stderr[-2000:])
import rdkit  # noqa: E402
assert rdkit.__version__ == RDKIT_PIN, rdkit.__version__

import numpy as np  # noqa: E402
import pyarrow.parquet as pq  # noqa: E402

from casmi_scratch import audit  # noqa: E402
from casmi_scratch.analog import label_match, vote_report  # noqa: E402
from casmi_scratch.config import Config  # noqa: E402
from casmi_scratch.library import load_library, remap_keys  # noqa: E402
from casmi_scratch.pool import load_keymap, load_np_labels, load_pool  # noqa: E402

CFG = Config().with_(frag_workers=WORKERS)
T0 = time.time()


def find(name):
    for depth in ("*", "*/*", "*/*/*"):
        hits = sorted(ROOT.glob(f"{depth}/{name}"), key=lambda p: len(str(p)))
        if hits:
            return hits[0]
    raise FileNotFoundError(f"{name} not found under {ROOT}")


def stage(name, fn):
    path = OUT / f"{name}.json"
    if path.exists():
        print(f"[{name}] cached")
        return json.loads(path.read_text())
    t = time.time()
    res = fn()
    path.write_text(json.dumps(res, indent=1, default=str))
    print(f"[{name}] {time.time() - t:.0f}s")
    return res


TRAIN = str(find("train.parquet"))
MANIFEST = json.loads((POOL_DIR / "MANIFEST.json").read_text())
assert MANIFEST["version"] == "v2" and "npc" in MANIFEST, "needs casmi26-scratch-pool v2 (run r2_npc_colab first)"
MOLS = audit.load_slice(TRAIN)
KEYMAP = load_keymap(str(POOL_DIR))
TRUTH = lambda ik: KEYMAP.get(ik, ik)  # noqa: E731
LIB = remap_keys(load_library(TRAIN, struct_mass=CFG.struct_mass), KEYMAP)
POOL, INFO = load_pool(str(POOL_DIR), drop_e180=True, with_npc=True)

NPC = pq.read_table(POOL_DIR / "pool_npc.parquet", columns=["key", "sc1", "pathway"]).to_pandas().set_index("key")
NEED = set(LIB.ik) | {TRUTH(ik) for ik, _ in MOLS}
NPC = NPC[NPC.index.isin(NEED)]
LEVEL = dict(np_superclass="sc1", np_pathway="pathway")
VOTE_LABEL = {k: v for k, v in NPC.sc1.items() if isinstance(v, str)}


def label_of(key, level):
    v = NPC.at[key, LEVEL[level]] if key in NPC.index else None
    return v if isinstance(v, str) and v else None


print(f"slice I: {len(MOLS)} molecules | pool {MANIFEST['version']} r1b {len(POOL):,} | "
      f"vote labels {len(VOTE_LABEL):,} | labeller {MANIFEST['npc'].get('labeller')}")

# %% [markdown]
# ## R2.3 discrimination (also gives every molecule's vote)

# %%
ROWS = stage("disc_rows", lambda: audit.discrimination(MOLS, LIB, POOL, TRUTH, VOTE_LABEL, CFG))
DISC = audit.summarize_discrimination(ROWS, CFG.topn)
print(json.dumps(DISC, indent=1))

# %% [markdown]
# ## R2.2 CV re-run (NPClassifier labels) + table-only purity

# %%
CV = stage("cv", lambda: audit.class_vote_diag(MOLS, LIB, TRUTH, label_of, CFG, modes=("delta",)))
TABLE = load_np_labels(str(POOL_DIR))
TABLE = TABLE[TABLE.label_source == 1]
votes = {r["ik"]: r["voted"] for r in ROWS}
tab_truth = [TABLE.at[TRUTH(ik), "np_superclass"] if TRUTH(ik) in TABLE.index else None for ik, _ in MOLS]
TABLE_ONLY = vote_report([votes.get(ik) for ik, _ in MOLS], tab_truth)
print(json.dumps(dict(cv=CV["delta"]["np_superclass"], pathway=CV["delta"]["np_pathway"], table_only=TABLE_ONLY),
                 indent=1, default=str))

# %% [markdown]
# ## Verdicts (pre-registered gates)

# %%
sc = CV["delta"]["np_superclass"]
verdicts = {"R2.2 CV (delta, NPClassifier labels)": CV["delta"]["pass"], "R2.3 discrimination": DISC["pass"]}
print(f"R2.2 coverage {sc['coverage']:.3f} purity {sc['purity']:.3f} baseline {sc['baseline']:.3f} "
      f"(majority {sc['majority']}); table-only purity {TABLE_ONLY['purity']:.3f} (n {TABLE_ONLY['n_voted']})")
print(f"R2.3 voted {DISC['n_voted']}/{DISC['n']} (in range {DISC['n_voted_in_range']}); truth above window median "
      f"{DISC['truth_above_median']:.3f}; up {DISC['up']} / down {DISC['down']}; reach {DISC['reach']:.3f}; "
      f"MRR@25 {DISC['mrr_before']:.4f} -> {DISC['mrr_after']:.4f}; median tier-2 fr gap {DISC['fr_gap_median']:.3f}")
for k, v in verdicts.items():
    print(f"  {'PASS' if v else 'FAIL'}  {k}")
(OUT / "verdicts.json").write_text(json.dumps(dict(verdicts=verdicts, disc=DISC, table_only=TABLE_ONLY,
                                                   total_s=round(time.time() - T0, 1)), indent=1, default=str))
